from hypothesis import strategies as st

@st.composite
def gen(draw):
    A = draw(st.integers(-4, 4))
    B = draw(st.integers(-4, 4))
    C = draw(st.integers(A + 1, 5))
    D = draw(st.integers(B + 1, 5))
    if draw(st.booleans()):
        # edge case: extreme-ish values scaled down
        A, B = -4, -4
        C, D = 4, 4
    return f"{A} {B} {C} {D}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 4:
        return False
    try:
        A, B, C, D = (int(x) for x in t)
    except ValueError:
        return False
    lim = 10**9
    return (all(-lim <= v <= lim for v in (A, B, C, D))
            and A < C and B < D)

def _black(x, y):
    # Color of a point not on any dividing line:
    # black iff floor(x) + floor(y/2) + floor((x+y)/2) is even.
    # (Checked: (0.5,0.5) gives 0 -> black; each boundary crossing flips parity.)
    s = floor(x) + floor(y / 2) + floor((x + y) / 2)
    return s % 2 == 0

def ref(inp):
    A, B, C, D = (int(x) for x in inp.split())
    total = 0  # doubled area
    for i in range(A, C):
        for j in range(B, D):
            s = i + j + 1
            if s % 2 == 0:
                # cell is split by the anti-diagonal x+y = s into two triangles
                # each triangle has doubled area 1
                p1 = (Fraction(i) + Fraction(1, 3), Fraction(j) + Fraction(1, 3))
                p2 = (Fraction(i) + Fraction(2, 3), Fraction(j) + Fraction(2, 3))
                if _black(*p1):
                    total += 1
                if _black(*p2):
                    total += 1
            else:
                c = (Fraction(i) + Fraction(1, 2), Fraction(j) + Fraction(1, 2))
                if _black(*c):
                    total += 2
    return str(total)
