def ref(inp):
    # Color of a point (x, y), not on any line, with x, y given as integers scaled by 10:
    # Each crossing of x = n, y = 2k, x+y = 2m flips exactly one of the three terms
    # floor(x), floor(y/2), floor((x+y)/2); the point (0.5, 0.5) gives 0 (black = even).
    def black(X, Y):
        # X = 10*x, Y = 10*y, so floor(x) = X//10, floor(y/2) = Y//20, floor((x+y)/2) = (X+Y)//20
        return (X // 10 + Y // 20 + (X + Y) // 20) % 2 == 0

    t = inp.split()
    A, B, C, D = (int(x) for x in t)
    # Every unit cell [i,i+1]x[j,j+1] is cut by at most one diagonal line, and the
    # interior is split into two triangles. Sample one point in each triangle:
    # local (0.2, 0.3) lies on the low side (local sum 0.5) and (0.8, 0.7) on the high side (local sum 1.5).
    # Each black triangle has doubled area 1; a cell with no cut has both samples equal and doubled area 2.
    # So the answer is the sum of [black] over the two samples per cell.
    total = 0
    for i in range(A, C):
        for j in range(B, D):
            if black(10 * i + 2, 10 * j + 3):
                total += 1
            if black(10 * i + 8, 10 * j + 7):
                total += 1
    return str(total)
