from hypothesis import strategies as st
from fractions import Fraction
import math

@st.composite
def gen(draw):
    mode = draw(st.integers(0, 3))
    if mode == 0:
        # small arbitrary rectangle
        A = draw(st.integers(-6, 5))
        C = draw(st.integers(A + 1, A + 7))
        B = draw(st.integers(-6, 5))
        D = draw(st.integers(B + 1, B + 7))
    elif mode == 1:
        # unit-ish rectangles at various offsets
        A = draw(st.integers(-4, 4))
        B = draw(st.integers(-4, 4))
        C = A + 1
        D = B + 1
    elif mode == 2:
        # rectangles touching the origin
        A = draw(st.integers(-3, 0))
        B = draw(st.integers(-3, 0))
        C = draw(st.integers(1, 4))
        D = draw(st.integers(1, 4))
    else:
        # extreme-ish values scaled down
        A = draw(st.sampled_from([-10**9, -10**9 + 1, 0]))
        C = draw(st.sampled_from([A + 1, 10**9, 10**9 - 1]))
        B = draw(st.sampled_from([-10**9, -10**9 + 1, 0]))
        D = draw(st.sampled_from([B + 1, 10**9, 10**9 - 1]))
        if C <= A:
            C = A + 1
        if D <= B:
            D = B + 1
    return f"{A} {B} {C} {D}\n"

def validate(inp):
    t = inp.split()
    if len(t) != 4:
        return False
    try:
        A, B, C, D = (int(x) for x in t)
    except ValueError:
        return False
    vals = (A, B, C, D)
    if not all(-10**9 <= v <= 10**9 for v in vals):
        return False
    return A < C and B < D

def _black(x, y):
    # Region coloring: point (x,y) (generic, not on any line) is black
    # iff floor(x) + floor(y/2) + floor((x+y)/2) is even.
    # Verified: (0.5,0.5) is black, and every line type flips color.
    p = math.floor(x)
    q = math.floor(y / 2)
    r = math.floor((x + y) / 2)
    return (p + q + r) % 2 == 0

def _cell_weight(i, j):
    # Contribution (twice the black area) of the unit cell [i,i+1]x[j,j+1],
    # where i, j are any integers with the given residues mod 4
    # (the coloring is invariant under shifting i or j by 4).
    if (i + j) % 2 == 0:
        # not cut by any line: single color, check the center
        return 2 if _black(Fraction(2 * i + 1, 2), Fraction(2 * j + 1, 2)) else 0
    # cut by the even line x+y = i+j+1 into two triangles of area 1/2 each
    w = 0
    if _black(Fraction(3 * i + 1, 3), Fraction(3 * j + 1, 3)):
        w += 1
    if _black(Fraction(3 * i + 2, 3), Fraction(3 * j + 2, 3)):
        w += 1
    return w

def _count_res(lo, hi, a):
    # number of integers t in [lo, hi-1] with t % 4 == a
    return (hi - 1 - a) // 4 - (lo - 1 - a) // 4

def ref(inp):
    t = inp.split()
    A, B, C, D = (int(x) for x in t)
    total = 0
    for a in range(4):
        ca = _count_res(A, C, a)
        if ca == 0:
            continue
        for b in range(4):
            cb = _count_res(B, D, b)
            if cb == 0:
                continue
            total += ca * cb * _cell_weight(a, b)
    return str(total)
